test("should interpolate arrays and objects in request payload body", () => {
  const resBody = res.getBody();
  const expectedOutput = {
    "undefined": "{{obj.undefined}}",
    "null": null,
    "number": 1,
    "boolean": true,
    "array": [
      1,
      2,
      3,
      4,
      5
    ],
    "array[0]": 1,
    "object": {
      "null": null,
      "number": 1,
      "boolean": true,
      "foo": {
        "bar": {
          "baz": 1
        }
      }
    },
    "object.foo": {
      "bar": {
        "baz": 1
      }
    },
    "object.foo.bar": {
      "baz": 1
    },
    "object.foo.bar.baz": 1
  };
  expect(resBody).to.be.eql(expectedOutput);
})
